"""Freeze the source-only grouped-kernel study, not a submission package."""
import pathlib,json,hashlib,datetime,shutil
P=pathlib.Path(__file__).resolve().parent;D=P/'pr50800_frozen';assert not D.exists();D.mkdir()
files=[('PR50800_READOUT.txt','READOUT.txt'),('PR50800_H200_PLAN.txt','H200_PLAN.txt'),('OTHER_ENGINE_SWEEP_READOUT.txt','OTHER_ENGINE_SWEEP.txt'),('pr50800_coefficient_audit.json','original/coefficient_audit.json'),('audit_pr50800_coefficients.py','original/coefficient_audit.py'),('pr50800_offline/device_only.cu','original/device_only.cu'),('pr50800_offline/extraction.json','original/extraction.json'),('pr50800_offline/compile.json','original/compile.json'),('pr50800_offline/compile.log','original/compile.log'),('pr50800_offline/compile.py','original/compile.py'),('sources/nov10_sweep/pr50800/manifest.json','original/upstream_manifest.json'),('pr50800_boundaries/device_only.cu','boundary/device_only.cu'),('pr50800_boundaries/transformation.json','boundary/transformation.json'),('pr50800_boundaries/compile.json','boundary/compile.json'),('pr50800_boundaries/compile.log','boundary/compile.log'),('pr50800_boundaries/compile.py','boundary/compile.py'),('pr50800_boundaries/coefficient_proof.json','boundary/coefficient_proof.json'),('prove_pr50800_boundaries.py','boundary/coefficient_proof.py'),('pr50800_rawscale/device_only_uncompiled.cu','rawscale/device_only_uncompiled.cu'),('pr50800_rawscale/coefficient_proof.json','rawscale/coefficient_proof.json'),('pr50800_rawscale/layout_proof.json','rawscale/layout_proof.json'),('prove_pr50800_rawscale_layout.py','rawscale/layout_proof.py'),('prepare_pr50800_rawscale.py','rawscale/prepare_source.py'),('forward_oracles.py','rawscale/forward_oracles.py'),('pr50800_progress_model.json','protocol/progress_model.json'),('model_pr50800_progress.py','protocol/progress_model.py'),('pr50800_route_ownership.json','protocol/route_ownership.json'),('prove_pr50800_routes.py','protocol/route_ownership.py')]
rows=[]
for src,dst in files:
 a=P/src;b=D/dst;b.parent.mkdir(exist_ok=True,parents=True);shutil.copyfile(a,b);raw=b.read_bytes();rows.append(dict(path=dst,original_source=src,sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw)))
for name in ('pr50800_offline','pr50800_boundaries'):
 a=P.parent/'coordination/wgmma_hazard_audit'/name/'complete_cfg_audit.json';b=D/('original' if name=='pr50800_offline' else 'boundary')/'corrected_cfg_audit.json';shutil.copyfile(a,b);raw=b.read_bytes();rows.append(dict(path=str(b.relative_to(D)),original_source=str(a),sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw)))
external=[]
for rel in ('pr50800_offline/pr50800_sm90a.cubin','pr50800_offline/sass.txt','pr50800_boundaries/boundary_sm90a.cubin','pr50800_boundaries/sass.txt'):
 p=P/rel;external.append(dict(path=rel,sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size))
for rel in ('original/device_only.cu','boundary/device_only.cu','rawscale/device_only_uncompiled.cu'):
 a=D/rel;maximum=max(map(len,a.read_text().splitlines()));assert maximum<=400
report=dict(frozen_utc=datetime.datetime.utcnow().isoformat()+'Z',files=rows,external_binary_artifacts=external,compiler='CUDA13.0.88,SM90a',raw_scale_variant_compiled=False,gpu_execution=False,serving_integration=False,submission_package=False,conclusive_2x_evidence=False,submission_authorized=False,scope='Original and boundary-restored device-only compile; independent CPU arithmetic/layout/protocol proofs; raw-scale source remains uncompiled. Corrected vendor-CFG audits are static only.',files_count=len(rows),total_frozen_bytes=sum(x['bytes'] for x in rows))
(D/'manifest.json').write_text(json.dumps(report,indent=2));print(json.dumps(dict(manifest_sha256=hashlib.sha256((D/'manifest.json').read_bytes()).hexdigest(),files=len(rows),bytes=report['total_frozen_bytes']),indent=2))
